async function startFixtureApp(session: ChannelSession) {
  const previous = ChannelSocket.current;
  // The UI owns automatic activation; this non-React fixture starts it explicitly.
  void session.activateApp().catch(() => {});
  await vi.waitFor(() => expect(ChannelSocket.current).not.toBe(previous));
  return ChannelSocket.current;
}

async function setup(window = 1000, read = true, hash = "room=first", readyInteractions = true, roomIds = ["first", "second"], storage: "saved" | "throws" | "ignores-write" = "saved", Session = ChannelSession) {
  vi.stubGlobal("location", new URL(`https://channel.test/__channel-preview${hash ? `#${hash}` : ""}`));
  const values = new Map<string, string>();
  vi.stubGlobal("localStorage", { getItem: (key: string) => values.get(key) ?? null, setItem: (key: string, value: string) => {
    if (storage === "throws") throw new Error("storage unavailable");
    if (storage === "saved") values.set(key, value);
  } });
  vi.stubGlobal("WebSocket", ChannelSocket);
  const session = new Session();
  type PeerRequest = Extract<ChannelCommand, { type: "chat" | "history" | "history_seek" | "delete_message" | "clear_history" }> & { requestId: string };
  type InteractionRequest = Extract<ChannelCommand, { type: "interaction_ready" | "react" }> & { requestId: string };
  const sent: PeerRequest[] = [], pending: PeerRequest[] = [];
  const interactions: InteractionRequest[] = [];
  const conversation = (session as unknown as { conversation: ChannelConversation }).conversation;
  vi.spyOn(conversation, "send").mockImplementation(async (command, requestId) => {
    if (command.type === "interaction_ready" || command.type === "react") {
      const request = { ...command, requestId };
      interactions.push(request);
      if (readyInteractions && command.type === "interaction_ready") queueMicrotask(() => peer.reply(request,
        { type: "interaction_ready", serverTime: Date.now(), reactionIds: ["wave", "heart", "future-decoration"], publicationReactions: [] }));
      return;
    }
    const request = { ...command, requestId };
    sent.push(request); pending.push(request);
  });
  const deliver = (reply: ConversationReply) => (session as unknown as { receiveConversation(value: ConversationReply): void }).receiveConversation(reply);
  const peer = {
    sent, interactions,
    async next() { await vi.waitFor(() => expect(pending.length).toBeGreaterThan(0)); return pending.shift()!; },
    reply(request: PeerRequest | InteractionRequest, record: ConversationReply["record"], bindingId = "binding") {
      const reply = { roomId: request.roomId, bindingId, sender: "host", recipient: "endpoint", requestId: request.requestId };
      deliver({ ...reply, record: "message" in record ? { ...record, message: messageSchema.parse(record.message) } : record });
      if (record.type === "confirmed") deliver({ ...reply, record: { type: "message_reactions", snapshot: {
        messageId: record.message.id, messageSeq: record.message.seq, ...(record.message.reactions ?? { revision: 0, counts: {} }),
      } } });
    },
    page(request: PeerRequest, messages: ChannelMessage[], hasMore = false, oldestSeq: number | null = 1, bindingId = "binding") {
      for (const message of messages) {
        peer.reply(request, { type: "history_message", message }, bindingId);
        peer.reply(request, { type: "message_reactions", snapshot: {
          messageId: message.id, messageSeq: message.seq, ...(message.reactions ?? { revision: 0, counts: {} }),
        } }, bindingId);
      }
      peer.reply(request, { type: "history_end", count: messages.length, hasMore, oldestSeq, before: "before" in request ? request.before ?? null : null }, bindingId);
    },
    live(message: ChannelMessage, roomId = "first", bindingId = "binding") {
      deliver({ roomId, bindingId, sender: "host", recipient: "endpoint", requestId: "live", record: { type: "live_message", message: messageSchema.parse(message) } });
    },
    async history(messages: ChannelMessage[], hasMore = false, older = false) {
      const loading = older ? session.loadHistory("first") : session.loadLatestHistory("first");
      peer.page(await peer.next(), messages, hasMore);
      await loading;
    },
  };
  session.start();
  const socket = ChannelSocket.current;
  await socket.onopen?.();
  socket.receive({ type: "welcome", protocol: CHANNEL_PROTOCOL, credential: "credential", sessionId: "endpoint", state: {
    channel: { id: "domain", name: "Friends", icon: "future-domain_7", ownerId: "self", roomCreationPolicy: "ordinary", hostingMode: "lightweight", historyWindow: window, userCount: 1, managedRoomIds: roomIds,
      rooms: roomIds.map(id => ({ id, name: id, icon: "couch", creatorId: "self", access: "public",
        hidden: false, hasPassword: false, authorized: true, canManage: true,
        participantSessionIds: id === "first" ? ["endpoint"] : [],
        historyLineage: crypto.randomUUID(), lastMessageSeq: 0, fileActivity: [],
        available: true, reading: id === "first", capabilities: { attachments: true },
        delivery: { hostSessionId: "host", bindingId: "binding" } })) },
    users: [{ id: "self", name: "Me", version: profileVersion }], sessions: [{ id: "endpoint", userId: "self", online: true, signingKey: testSigningKey }],
    publications: [], voice: [], subscriptions: [], watchActivities: [], watchSubscriptions: [], watchBytes: [], failedSubscriptions: [], files: [], pairs: [], iceServers: [],
  } });
  if (read) {
    const browse = socket.sent.findLast(command => command.type === "browse" && command.active)!;
    socket.receive({ type: "ack", requestId: browse.requestId });
    peer.page(await peer.next(), [], false, null);
    await vi.waitFor(() => expect(session.getSnapshot().pending.has("history:first")).toBe(false));
    peer.sent.length = 0;
  }
  return { session, socket, peer };
}

async function ackSourceUpdate(socket: ChannelSocket): Promise<void> {
  await vi.waitFor(() => expect(socket.sent.at(-1)?.type).toBe("publish"));
  socket.receive({ type: "ack", requestId: socket.sent.at(-1)!.requestId });
}

const message = (seq: number) => ({ id: `message-${seq}`, seq, userId: "self", text: `Hello ${seq}`, time: seq, attachments: [],
  reactions: { revision: 0, counts: {} } });
const reactionSnapshot = (seq: number, revision: number, counts: Record<string, number> = {}) =>
  ({ messageId: `message-${seq}`, messageSeq: seq, revision, counts });

test("writer-confirmed moderation removes messages, quotations and transfers for both readers", async () => {
  const moderator = await setup();
  const reader = await setup();
  const quoted = { ...message(3), reply: { seq: 1, userId: "self", text: "Deleted quotation", notify: true } };
  const readerTransfers = vi.spyOn(reader.session.attachments, "removeMessages");
  try {
    for (const { session, socket, peer } of [moderator, reader]) {
      const state = session.getSnapshot().state!;
      socket.receive({ type: "state", state: { ...state, channel: { ...state.channel, rooms: state.channel.rooms.map(room =>
        room.id === "first" ? { ...room, lastMessageSeq: 3 } : room) } } });
      await peer.history([message(1), message(2), quoted]);
    }
    vi.stubGlobal("localStorage", { getItem: () => null, setItem: () => {} });
    const deletion = moderator.session.deleteMessage("first", 1, message(1).id);
    const request = await moderator.peer.next();
    expect(request).toMatchObject({ type: "delete_message", messageSeq: 1, messageId: message(1).id });
    expect(moderator.session.getSnapshot().messagesByRoom.first).toHaveLength(3);
    reader.peer.reply(request, { type: "message_deleted", messageSeq: 1 }, "retired-binding");
    expect(reader.session.getSnapshot().messagesByRoom.first).toHaveLength(3);
    for (const { peer } of [moderator, reader]) peer.reply(request, { type: "message_deleted", messageSeq: 1 });
    await deletion;
    for (const { session } of [moderator, reader]) {
      const messages = session.getSnapshot().messagesByRoom.first;
      expect(messages.map(item => item.seq)).toEqual([2, 3]);
      expect(messages[1].reply).toBeUndefined();
    }
    const [room, removed] = readerTransfers.mock.calls[0];
    expect([room, removed(1), removed(2)]).toEqual(["first", true, false]);

    const clearing = moderator.session.purgeRoomHistory("first");
    const purge = await moderator.peer.next();
    expect(purge).toMatchObject({ type: "clear_history", throughSeq: 3 });
    const older = reader.session.loadLatestHistory("first");
    const history = await reader.peer.next();
    for (const { peer } of [moderator, reader]) peer.reply(purge, { type: "history_cleared", throughSeq: 3 });
    await clearing;
    reader.peer.page(history, [message(2), quoted]);
    await older;
    reader.peer.live(message(3));
    reader.peer.live(message(4));
    expect(reader.session.getSnapshot().messagesByRoom.first.map(item => item.seq)).toEqual([4]);
    expect(reader.session.getSnapshot().readByRoom.first).toBe(3);
    expect(moderator.session.getSnapshot().messagesByRoom.first).toEqual([]);
  } finally { reader.session.close(); moderator.session.close(); }
});

test("confirmed clear through the predecessor of the retained page closes earlier history", async () => {
  const { session, peer } = await setup();
  try {
    const rows = Array.from({ length: 50 }, (_, i) => message(i + 2));
    await peer.history(rows, true);
    const before = session.getSnapshot().historyByRoom.first;
    expect(before).toMatchObject({ before: 2, hasMore: true });
    peer.reply({ type: "clear_history", roomId: "first", throughSeq: 1, requestId: "moderation" },
      { type: "history_cleared", throughSeq: 1 });
    expect(session.getSnapshot().messagesByRoom.first.map(row => row.seq)).toEqual(rows.map(row => row.seq));
    expect(session.getSnapshot().historyByRoom.first.hasMore).toBe(false);
  } finally { session.close(); }
});

test("an older page in flight observes the confirmed clear at the retained predecessor", async () => {
  const { session, peer } = await setup();
  try {
    await peer.history(Array.from({ length: 50 }, (_, i) => message(i + 52)), true);
    const reading = session.loadHistory("first"), request = await peer.next();
    peer.reply({ type: "clear_history", roomId: "first", throughSeq: 1, requestId: "moderation" },
      { type: "history_cleared", throughSeq: 1 });
    peer.page(request, Array.from({ length: 50 }, (_, i) => message(i + 2)), true);
    await reading;
    expect(session.getSnapshot().historyByRoom.first).toMatchObject({ before: 2, hasMore: false });
  } finally { session.close(); }
});

test("an empty latest history page confirms only the sequence visible when requested", async () => {
  const { session, socket, peer } = await setup();
  try {
    const state = structuredClone(session.getSnapshot().state!);
    state.channel.rooms[0].lastMessageSeq = 3;
    socket.receive({ type: "state", state });
    const loading = session.loadLatestHistory("first"), request = await peer.next();
    state.channel.rooms[0].lastMessageSeq = 7;
    socket.receive({ type: "state", state });
    peer.page(request, [], false, null);
    await loading;
    expect(session.getSnapshot().historyByRoom.first.emptyThrough).toBe(3);
    expect(session.getSnapshot().readByRoom.first).toBe(0);

    await peer.history([message(5)], true);
    const older = session.loadHistory("first"), previous = await peer.next();
    expect(previous).toMatchObject({ type: "history", before: 5 });
    peer.page(previous, [], false, null);
    await older;
    expect(session.getSnapshot().historyByRoom.first.emptyThrough).toBeUndefined();
  } finally { session.close(); }
});

test("a history clear waiting for browse cannot apply its previous range to a new binding", async () => {
  const { session, socket, peer } = await setup();
  const send = vi.mocked((session as unknown as { conversation: ChannelConversation }).conversation.send);
  try {
    const state = structuredClone(session.getSnapshot().state!);
    state.channel.rooms[0].lastMessageSeq = 18;
    socket.receive({ type: "state", state });
    const clearing = expect(session.purgeRoomHistory("first")).rejects.toThrow("room_unavailable");
    state.channel.rooms[0].delivery!.bindingId = "replacement";
    state.channel.rooms[0].lastMessageSeq = 30;
    socket.receive({ type: "state", state });
    await clearing;
    expect(send.mock.calls.some(([command]) => command.type === "clear_history")).toBe(false);

    socket.receive({ type: "ack", requestId: socket.sent.findLast(command => command.type === "browse" && command.active)!.requestId });
    peer.page(await peer.next(), [message(30)], false, 30, "replacement");
    const fresh = session.purgeRoomHistory("first");
    const command = await peer.next();
    expect(command).toMatchObject({ type: "clear_history", throughSeq: 30 });
    expect(send).toHaveBeenLastCalledWith(expect.objectContaining({ type: "clear_history" }), command.requestId, "replacement");
    peer.reply(command, { type: "history_cleared", throughSeq: 30 }, "replacement");
    await fresh;
  } finally { session.close(); }
});

test("the owner submits room creation policy and reads the authoritative update", async () => {
  const { session, socket } = await setup(1000, false);
  try {
    const state = session.getSnapshot().state!;
    const pending = session.setRoomCreationPolicy("invite_only", false);
    const command = socket.sent.findLast(command => command.type === "set_room_creation_policy")!;
    expect(command).toMatchObject({ type: "set_room_creation_policy", policy: "invite_only" });
    expect(session.getSnapshot().state?.channel.roomCreationPolicy).toBe("ordinary");
    socket.receive({ type: "state", state: { ...state, channel: { ...state.channel, roomCreationPolicy: "invite_only" } } });
    socket.receive({ type: "ack", requestId: command.requestId });
    await pending;
    expect(session.getSnapshot().state?.channel.roomCreationPolicy).toBe("invite_only");
  } finally { session.close(); }
});

test("a hosted site creates and binds the room before the browser enters it", async () => {
  const { session, socket } = await setup(1000, false, "");
  const loadHosting = vi.spyOn(hosting, "loadRoomHosting");
  try {
    const state = session.getSnapshot().state!;
    socket.receive({ type: "state", state: { ...state, channel: { ...state.channel, hostingMode: "hosted" } } });
    await vi.waitFor(() => expect(session.getSnapshot().state?.channel.hostingMode).toBe("hosted"));
    const picture = "data:image/png;base64,YWJj";
    const pending = session.createRoom({ name: "Hosted room", icon: "couch", picture, access: "private", hidden: true, password: "fixture", allowServiceRelay: false });
    await vi.waitFor(() => expect(socket.sent.at(-1)?.type).toBe("create_room"));
    const create = socket.sent.at(-1)!;
    expect(create).toMatchObject({ type: "create_room", room: { icon: "couch", access: "private", hidden: true, hasPassword: true },
      picture, password: "fixture", allowServiceRelay: false });
    expect(create.room).not.toHaveProperty("picture");
    socket.receive({ type: "room_created", requestId: create.requestId, room: { ...create.room as object, id: "hosted-room" } });
    await vi.waitFor(() => expect(socket.sent.at(-1)).toMatchObject({ type: "browse", roomId: "hosted-room", active: true }));
    socket.receive({ type: "ack", requestId: socket.sent.at(-1)!.requestId });
    expect(await pending).toBe("hosted-room");
    expect(loadHosting).not.toHaveBeenCalled();
    expect(socket.sent.some(command => command.type === "host_register")).toBe(false);
  } finally { session.close(); }
});

test("profile reads batch and deduplicate missing IDs without deleting retained identities", async () => {
  const { session, socket } = await setup(1000, false); socket.autoProfiles = false;
  const ids = Array.from({ length: 65 }, (_, index) => `offline-${index}`);
  try {
    const pending = session.loadProfiles([...ids, ...ids]);
    expect(socket.sent.filter(command => command.type === "profiles")).toHaveLength(1);
    const shared = session.loadProfiles(ids);
    expect(socket.sent.filter(command => command.type === "profiles")).toHaveLength(1);
    for (let index = 0; index < 3; index++) {
      await vi.waitFor(() => expect(socket.sent.filter(command => command.type === "profiles")).toHaveLength(index + 1));
      const request = socket.sent.filter(command => command.type === "profiles")[index];
      const profiles = (request.ids as string[]).filter(id => id !== "offline-64").map(id => ({ id, name: id, avatar: null, version: profileVersion }));
      socket.receive({ type: "profiles", requestId: request.requestId, profiles, total: profiles.length, nextCursor: null });
    }
    expect(await pending).toHaveLength(64); expect(await shared).toHaveLength(64);
    expect(socket.sent.filter(command => command.type === "profiles").map(request => (request.ids as string[]).length)).toEqual([32, 32, 1]);
    expect(await session.loadProfiles(ids)).toHaveLength(64);
    expect(socket.sent.filter(command => command.type === "profiles")).toHaveLength(3);
    expect(session.getSnapshot().profiles.get("offline-0")?.name).toBe("offline-0");
    expect(session.getSnapshot().state!.users).toHaveLength(1);
  } finally { session.close(); }
});

test("large offline profile demands keep only one bounded batch in flight", async () => {
  const { session, socket } = await setup(1000, false); socket.autoProfiles = false;
  let current = 0, maximum = 0;
  const send = socket.send.bind(socket);
  vi.spyOn(socket, "send").mockImplementation(data => {
    const request = JSON.parse(data); send(data);
    if (request.type !== "profiles") return;
    current++; maximum = Math.max(maximum, current);
    queueMicrotask(() => {
      current--;
      const profiles = request.ids.map((id: string) => ({ id, name: id, avatar: null, version: profileVersion }));
      socket.receive({ type: "profiles", requestId: request.requestId, profiles, total: profiles.length, nextCursor: null });
    });
  });
  try {
    const ids = Array.from({ length: 2112 }, (_, index) => `history-user-${index}`);
    expect(await session.loadProfiles(ids)).toHaveLength(ids.length);
    expect(socket.sent.filter(command => command.type === "profiles")).toHaveLength(66);
    expect(maximum).toBe(1);
  } finally { session.close(); }
});

test("profile versions refresh names and clear avatars while a new Welcome resets display facts", async () => {
  const { session, socket } = await setup(1000, false); socket.autoProfiles = false;
  const picture = "data:image/png;base64,YWJj";
  try {
    const state = structuredClone(session.getSnapshot().state!);
    state.users.push({ id: "friend", name: "Before", version: profileVersion }); state.channel.userCount++;
    socket.receive({ type: "state", state });
    socket.receive({ type: "profiles", requestId: socket.sent.at(-1)!.requestId, profiles: [{ ...state.users[1], avatar: picture }], total: 1, nextCursor: null });
    expect(session.getSnapshot().profiles.get("friend")?.avatar).toBe(picture);
    const next = structuredClone(state); next.users[1] = { id: "friend", name: "After", version: "1".repeat(64) };
    socket.receive({ type: "state", state: next });
    socket.receive({ type: "profiles", requestId: socket.sent.at(-1)!.requestId, profiles: [{ ...next.users[1], avatar: null }], total: 1, nextCursor: null });
    expect(session.getSnapshot().profiles.get("friend")).toEqual({ ...next.users[1], avatar: null });
    const resumed = structuredClone(next); resumed.users = [resumed.users[0]];
    socket.receive({ type: "welcome", protocol: CHANNEL_PROTOCOL, credential: "credential", sessionId: "endpoint", state: resumed });
    expect(session.getSnapshot().self).toEqual({ ...resumed.users[0], avatar: null });
    expect(session.getSnapshot().profiles.has("friend")).toBe(false);
    const reload = session.loadProfiles(["friend"]);
    socket.receive({ type: "profiles", requestId: socket.sent.at(-1)!.requestId, profiles: [{ ...next.users[1], avatar: null }], total: 1, nextCursor: null });
    expect(await reload).toEqual([{ ...next.users[1], avatar: null }]);
  } finally { session.close(); }
});

test("losing the live summary cannot revive a superseded offline author profile", async () => {
  const { session, socket } = await setup(1000, false);
  socket.autoProfiles = false;
  try {
    const base = structuredClone(session.getSnapshot().state!);
    const friend = { id: "friend", name: "Before", version: profileVersion };
    base.channel.userCount++;
    const state = { ...base, users: [...base.users, friend], sessions: [...base.sessions, { ...base.sessions[0], id: "friend-endpoint", userId: friend.id }] };
    socket.receive({ type: "state", state });
    socket.receive({ type: "profiles", requestId: socket.sent.at(-1)!.requestId, profiles: [{ ...friend, avatar: "data:image/png;base64,YWJj" }], total: 1, nextCursor: null });
    await session.loadProfiles([friend.id]);

    const current = { ...friend, name: "After", version: "1".repeat(64) };
    vi.useFakeTimers();
    socket.receive({ type: "state", state: { ...state, users: [...base.users, current] } });
    socket.receive({ type: "state", state: base });
    await vi.advanceTimersByTimeAsync(30000);
    expect(session.getSnapshot().profiles.has(friend.id)).toBe(false);

    const reading = session.loadProfiles([friend.id]);
    socket.receive({ type: "profiles", requestId: socket.sent.at(-1)!.requestId, profiles: [{ ...current, avatar: null }], total: 1, nextCursor: null });
    expect(await reading).toEqual([{ ...current, avatar: null }]);
  } finally { session.close(); }
});

test("profile directory abort ignores its late full-avatar reply and uses the content read deadline", async () => {
  const { session, socket } = await setup(1000, false); socket.autoProfiles = false; vi.useFakeTimers();
  try {
    const abort = new AbortController(), reading = session.queryProfiles({ query: "offline" }, abort.signal);
    const rejected = expect(reading).rejects.toMatchObject({ name: "AbortError" }), request = socket.sent.at(-1)!;
    abort.abort(); await rejected;
    socket.receive({ type: "profiles", requestId: request.requestId, profiles: [{ id: "late", name: "Late", avatar: null, version: profileVersion }], total: 1, nextCursor: null });
    expect(session.getSnapshot().profiles.has("late")).toBe(false);
    const slower = session.queryProfiles({}), failed = expect(slower).rejects.toThrow("request_timeout");
    await vi.advanceTimersByTimeAsync(10000); expect(session.getSnapshot().connection).toBe("connected");
    expect((session as unknown as { requests: Map<string, unknown> }).requests.has(socket.sent.at(-1)!.requestId as string)).toBe(true);
    await vi.advanceTimersByTimeAsync(20000); await failed;
  } finally { session.close(); }
});

