test.each(["room_already_hosted", "room_creation_restricted", "storage_failed"])("Browser handles %s during room registration on reconnect", async denial => {
  const policy = (id: string) => ({ id, creatorId: "self", name: id, icon: "couch", access: id === "second" ? "private" : "public", hidden: id === "second" });
  let ids = ["second"];
  const hosts = new Map(["first", "second"].map(id => [id, {
    roomId: id, summary: () => policy(id), close: vi.fn(async () => {}), bind: vi.fn(async () => {}),
  }]));
  vi.stubGlobal("indexedDB", {});
  vi.spyOn(hosting, "loadRoomHosting").mockResolvedValue({ BrowserRoomHost: {
    storedRoomIds: async () => ids,
    openExisting: async (_database: string, id: string) => hosts.get(id),
  } } as unknown as Awaited<ReturnType<typeof hosting.loadRoomHosting>>);
  const { session, socket } = await setup();
  try {
    await vi.waitFor(() => expect(socket.sent.some(command => command.type === "host_register")).toBe(true));
    const register = socket.sent.find(command => command.type === "host_register")!;
    socket.receive({ type: "host_bound", roomId: "second", bindingId: "own-binding" });
    socket.receive({ type: "ack", requestId: register.requestId });
    const state = structuredClone(session.getSnapshot().state!);
    state.channel.ownerId = "operator";
    state.channel.managedRoomIds = [];
    state.channel.rooms[1].access = "private";
    state.channel.rooms[1].hidden = true;
    if (denial === "room_creation_restricted") {
      state.channel.roomCreationPolicy = "invite_only";
      state.channel.rooms[0].available = false;
      delete state.channel.rooms[0].delivery;
    } else {
      state.channel.rooms[0].delivery = { hostSessionId: "other-page", bindingId: "other-binding" };
    }
    state.channel.rooms[1].delivery = { hostSessionId: "endpoint", bindingId: "own-binding" };
    ids = ["first", "second"];
    session.reconnect();
    const resumed = ChannelSocket.current; await resumed.onopen?.();
    resumed.receive({ type: "welcome", protocol: CHANNEL_PROTOCOL, credential: "credential", sessionId: "endpoint", state });
    await vi.waitFor(() => expect(resumed.sent.some(command => command.type === "host_register")).toBe(true));
    const conflict = resumed.sent.find(command => command.type === "host_register")!;
    expect(conflict.room).toMatchObject({ id: "first" });
    resumed.receive({ type: "error", requestId: conflict.requestId, code: denial });
    if (denial === "storage_failed") {
      await vi.waitFor(() => expect(session.getSnapshot().error).toBe(denial));
      expect(resumed.sent.filter(command => command.type === "host_register")).toEqual([conflict]);
      return;
    }
    await vi.waitFor(() => expect(resumed.sent.filter(command => command.type === "host_register")).toHaveLength(2));
    const own = resumed.sent.findLast(command => command.type === "host_register")!;
    expect(own).toMatchObject({ room: { id: "second" }, resumeBinding: "own-binding" });
    resumed.receive({ type: "host_bound", roomId: "second", bindingId: "own-binding" });
    resumed.receive({ type: "ack", requestId: own.requestId });
    expect(hosts.get("first")!.close).toHaveBeenCalledOnce();
    expect(hosts.get("second")!.close).not.toHaveBeenCalled();
    expect(resumed.sent.some(command => command.type === "host_stop")).toBe(false);
    expect(session.getSnapshot().error).toBeNull();
  } finally { session.close(); }
});

test.each(["registered", "retry-registration"])("Browser hosting does not depend on automatic App activation (%s)", async outcome => {
  const discovery = vi.spyOn(appLink, "discoverChannelAppHealth").mockResolvedValue(null);
  const host = {
    roomId: "", summary: () => ({ id: host.roomId, name: "Browser room", icon: "couch", creatorId: "self", access: "public" as const, hidden: false, hasPassword: false }),
    bind: async () => {}, close: async () => {},
  };
  let storedPolicy: string | undefined;
  vi.stubGlobal("indexedDB", {});
  vi.spyOn(hosting, "loadRoomHosting").mockResolvedValue({
    createRoomPolicy: async (input: unknown) => JSON.stringify(input),
    BrowserRoomHost: { storedRoomIds: async () => storedPolicy ? [host.roomId] : [], openExisting: async () => host,
      open: async (_database: string, policy: string) => { storedPolicy = policy; host.roomId = JSON.parse(policy).id; return host; } },
  } as unknown as Awaited<ReturnType<typeof hosting.loadRoomHosting>>);
  const { session, socket } = await setup();
  try {
    expect(discovery).not.toHaveBeenCalled();
    expect(session.getSnapshot()).toMatchObject({ appConnected: false, error: null });
    const creating = session.createRoom({ name: "Browser room", icon: "couch", access: "public", hidden: false });
    acceptCreatedRoom(socket);
    await vi.waitFor(() => expect(socket.sent.some(command => command.type === "host_register")).toBe(true));
    const register = socket.sent.find(command => command.type === "host_register")!;
    if (outcome === "retry-registration") {
      socket.receive({ type: "error", requestId: register.requestId, code: "room_host_conflict" });
      await expect(creating).rejects.toBeInstanceOf(RoomCreationInterrupted);
      await expect(creating).rejects.toMatchObject({ roomId: host.roomId, committed: true, message: "room_created_connection_failed" });
      expect(socket.sent.some(command => command.type === "cancel_room_creation" || command.type === "delete_room")).toBe(false);
      const state = structuredClone(session.getSnapshot().state!);
      state.channel.rooms[0].name = host.summary().name;
      state.channel.rooms.push({ ...state.channel.rooms[0], ...host.summary(), available: false, delivery: undefined });
      session.reconnect();
      const resumed = ChannelSocket.current;
      await resumed.onopen?.();
      expect(resumed.sent.find(command => command.type === "join")).toMatchObject({ credential: "credential" });
      resumed.receive({ type: "welcome", protocol: CHANNEL_PROTOCOL, credential: "credential", sessionId: "endpoint", state });
      await vi.waitFor(() => expect(resumed.sent).toContainEqual(expect.objectContaining({ type: "host_register", room: host.summary() })));
      const retry = resumed.sent.find(command => command.type === "host_register")!;
      resumed.receive({ type: "host_bound", roomId: host.roomId, bindingId: "retry-binding" });
      resumed.receive({ type: "ack", requestId: retry.requestId });
      return;
    }
    socket.receive({ type: "host_bound", roomId: host.roomId, bindingId: "browser-binding" });
    socket.receive({ type: "ack", requestId: register.requestId });
    await vi.waitFor(() => expect(socket.sent.some(command => command.type === "browse" && command.roomId === host.roomId)).toBe(true));
    const browse = socket.sent.findLast(command => command.type === "browse" && command.roomId === host.roomId)!;
    socket.receive({ type: "room_reply", roomId: host.roomId, requestId: browse.requestId, result: { type: "done" } });
    await expect(creating).resolves.toBe(host.roomId);
    expect(discovery).not.toHaveBeenCalled();
    await expect(session.activateApp()).rejects.toThrow("app_disconnected");
    expect(session.getSnapshot().error).toBeNull();
  } finally { session.close(); }
});

test.each(["policy", "open"])("Browser room creation cancels its reservation after %s fails", async failure => {
  const { session, socket, stage, open } = await setupRoomBackup();
  const runtime = await hosting.loadRoomHosting();
  vi.mocked(hosting.loadRoomHosting).mockResolvedValue({ ...runtime, createRoomPolicy: async () => {
    if (failure === "policy") throw new Error("policy_failed");
    return stage.policy;
  } });
  if (failure === "open") open.mockRejectedValueOnce(new Error("open_failed"));
  try {
    const creating = session.createRoom({ name: "Browser room", icon: "couch", access: "public", hidden: false });
    await expect(creating).rejects.toThrow(failure + "_failed");
    await expect(creating).rejects.not.toBeInstanceOf(RoomCreationInterrupted);
    expect(socket.sent.filter(command => command.type === "cancel_room_creation")).toEqual([
      expect.objectContaining({ roomId: "domain-created-room" }),
    ]);
    expect(socket.sent.some(command => command.type === "delete_room")).toBe(false);
  } finally { session.close(); }
});

