test("backup WASM failures preserve operation error copy and allow the next valid archive", async () => {
  const core = await import("../prototype/channel-browser/pkg/piik_channel_browser.js");
  const { readFile } = await import("node:fs/promises");
  await core.default({ module_or_path: await readFile("prototype/channel-browser/pkg/piik_channel_browser_bg.wasm") });
  vi.spyOn(hosting, "loadRoomHosting").mockResolvedValue({ ...core, initializeRuntime: async () => {} } as never);
  const metadata: backupArchive.BackupMetadata = { kind: "room_copy", version: 2, authors: {}, retainedFiles: [] };
  const unsupported = { ...metadata, version: 999 } as unknown as typeof metadata;
  const zip = await import("@zip.js/zip.js/lib/zip-core-native.js");
  const writer = new zip.ZipWriter(new zip.BlobWriter("application/zip"), { useWebWorkers: false, compressionMethod: 0, level: 0 });
  await writer.add("manifest.json", new zip.TextReader(JSON.stringify(unsupported)));
  await writer.add("history.ndjson", new zip.TextReader(""));
  const invalid = await writer.close();
  const visitor = { metadata: vi.fn(), row: vi.fn(), content: vi.fn() };
  const emptyRows = async function* () {};
  for (const operation of [() => backupArchive.readBackup(invalid, visitor), () => backupArchive.writeBackup(unsupported, emptyRows())]) {
    const error = await operation().catch(error => error);
    expect(error).toBeInstanceOf(Error);
    expect(error.message).toBe("unsupported_backup_version");
    expect(channelErrorPresentation(error.message, key => en[key]).message).toBe(en["channel.error.unsupportedBackupVersion"]);
  }
  expect(visitor.metadata).not.toHaveBeenCalled(); expect(visitor.row).not.toHaveBeenCalled(); expect(visitor.content).not.toHaveBeenCalled();
  const valid = await backupArchive.writeBackup(metadata, emptyRows());
  await expect(backupArchive.readBackup(valid)).resolves.toEqual(metadata);
  const existing = new Error("owned private archive detail", { cause: new Error("owned cause") });
  visitor.metadata.mockImplementation(() => { throw existing; });
  await expect(backupArchive.readBackup(valid, visitor)).rejects.toBe(existing);
  expect(channelErrorPresentation(existing.message, key => en[key]).message).toBe(en["channel.error.actionFailed"]);
});

test("a copy without room information round-trips real ZIP content and remaps historical identity in Core", async () => {
  const core = await import("../prototype/channel-browser/pkg/piik_channel_browser.js");
  const { readFile } = await import("node:fs/promises");
  await core.default({ module_or_path: await readFile("prototype/channel-browser/pkg/piik_channel_browser_bg.wasm") });
  const { session, snapshot, row, read } = await setupRoomBackup();
  read.mockRestore();
  vi.mocked(hosting.loadRoomHosting).mockResolvedValue({ ...core, initializeRuntime: async () => {} } as never);
  const author = crypto.randomUUID(), creator = crypto.randomUUID(), messageId = crypto.randomUUID();
  const file = new File(["owned copy bytes"], "owned.txt"), hash = new core.AttachmentHash();
  hash.update(new Uint8Array(await file.arrayBuffer()));
  const attachment = { id: crypto.randomUUID(), name: file.name, size: file.size,
    mediaType: "application/octet-stream" as const, sha256: hash.finish() };
  Object.assign(row, { id: messageId, userId: author, nonce: "owned-copy-nonce", archivedAuthorName: "Archived author",
    attachments: [attachment], reactions: { revision: 1, counts: { wave: 1 } } });
  vi.spyOn(session.attachments, "retained").mockResolvedValue([
    { key: { roomId: "first", messageSeq: row.seq, attachmentId: attachment.id }, attachment, file },
  ]);
  const history: BackupHistoryRow[] = [], content = new Map<string, File>();
  let importer: InstanceType<typeof core.CopyHistoryImport> | undefined;
  try {
    const archive = await session.exportRoomCopy("first", false);
    const metadata = await backupArchive.readBackup(archive, {
      metadata: () => {}, row: value => { history.push(value); }, content: (digest, value) => { content.set(digest, value); },
    });
    expect(metadata).toEqual({ kind: "room_copy", version: 2, authors: {}, retainedFiles: [{ messageSeq: row.seq, attachment }] });
    // A copy excludes room authority; it is not anonymized history before import.
    expect(history).toEqual([row]);
    expect(await content.get(attachment.sha256)!.text()).toBe("owned copy bytes");
    const hostedCopySettings = { type: "create_room" as const, room: {
      id: "new", creatorId: author, name: "Hosted copy", icon: "couch", access: "public" as const, hidden: false,
      hasPassword: false, voiceBitrate: 64_000, relayCapacity: 4,
    } };
    const { archive: requestArchive } = await backupArchive.prepareHostedRoomArchive(archive,
      { kind: "room_copy", settings: hostedCopySettings }, () => {});
    const zip = await import("@zip.js/zip.js/lib/zip-core-native.js");
    const reader = new zip.ZipReader(new zip.BlobReader(requestArchive!), { useWebWorkers: false });
    try {
      const entries = await reader.getEntries();
      expect(entries.map(entry => entry.filename).sort()).toEqual(["history.ndjson", "manifest.json", "settings.json"]);
      const settingsEntry = entries.find(entry => entry.filename === "settings.json")!;
      if (settingsEntry.directory) throw new Error("invalid settings entry");
      expect(JSON.parse(await settingsEntry.getData(new zip.TextWriter()))).toEqual(hostedCopySettings);
    } finally { await reader.close(); }
    importer = new core.CopyHistoryImport(JSON.stringify(metadata));
    const copied = JSON.parse(importer.accept(JSON.stringify(history[0]))) as BackupHistoryRow;
    importer.finish();
    expect(copied).toMatchObject({ seq: row.seq, text: row.text, attachments: [attachment],
      archivedAuthorName: "Archived author", reactions: row.reactions });
    if (!("id" in copied)) throw new Error("expected live archive message");
    expect(copied.id).not.toBe(messageId); expect(copied.userId).not.toBe(author); expect(copied.nonce).not.toBe(row.nonce);
    const policy = JSON.parse(core.create_room_policy(JSON.stringify({ id: crypto.randomUUID(), creatorId: creator,
      name: "New copy", icon: "couch", access: "private", hidden: false })));
    const converted = await backupArchive.writeBackup({ kind: "room", version: 3, domainId: crypto.randomUUID(), policy,
      retainedFiles: metadata.kind === "room_copy" ? metadata.retainedFiles : [] },
      (async function* () { yield copied; })(), async entry => content.get(entry.attachment.sha256)!);
    const restored: BackupHistoryRow[] = [];
    const result = await backupArchive.readBackup(converted, { metadata: () => {}, row: value => { restored.push(value); }, content: () => {} });
    expect(result).toMatchObject({ kind: "room", policy: { creatorId: creator, access: "private", grants: [], inviteHash: null, passwordHash: null } });
    expect(result).not.toHaveProperty("ownCredential"); expect(policy).not.toHaveProperty("inviteKey");
    const target = { kind: "room" as const, domainId: result.kind === "room" ? result.domainId : "", roomId: policy.id };
    await expect(backupArchive.prepareHostedRoomArchive(archive, target, () => {})).rejects.toThrow("backup_room_mismatch");
    const { archive: writerArchive, contents } = await backupArchive.prepareHostedRoomArchive(converted, target, () => {});
    expect(await contents.get(attachment.sha256)!.text()).toBe("owned copy bytes");
    const uploaded: BackupHistoryRow[] = [];
    const stripped = await backupArchive.readBackup(writerArchive!, { metadata() {}, row(value) { uploaded.push(value); },
      content() { throw new Error("unexpected hosted content"); } });
    expect((await backupArchive.prepareHostedRoomArchive(writerArchive, target, () => {})).archive).toBe(writerArchive);
    expect(stripped).toEqual({ ...result, retainedFiles: [] });
    expect(uploaded).toEqual(restored);
    expect(restored).toEqual([copied]); expect(snapshot.close).toHaveBeenCalledOnce();
  } finally { importer?.free(); session.close(); }
});

test.each(["backup", "copy", "copy-with-settings"] as const)("%s without file originals preserves every history row and inline image in the real ZIP", async kind => {
  const core = await import("../prototype/channel-browser/pkg/piik_channel_browser.js");
  const { readFile } = await import("node:fs/promises");
  await core.default({ module_or_path: await readFile("prototype/channel-browser/pkg/piik_channel_browser_bg.wasm") });
  const { session, socket, state, snapshot, row, read } = await setupRoomBackup();
  read.mockRestore();
  vi.mocked(hosting.loadRoomHosting).mockResolvedValue({ ...core, initializeRuntime: async () => {} } as never);
  const picture = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a1XcAAAAASUVORK5CYII=";
  const policy = JSON.parse(core.create_room_policy(JSON.stringify({ id: "first", creatorId: crypto.randomUUID(),
    name: "Owned room", icon: "rocket", picture, access: "private", hidden: false })));
  expect(policy).toMatchObject({ icon: "rocket", picture });
  snapshot.policy = JSON.stringify(policy);
  state.channel.id = crypto.randomUUID(); socket.receive({ type: "state", state });
  const hash = new core.AttachmentHash(); hash.update(new TextEncoder().encode("GIF89a"));
  const attachment = { id: crypto.randomUUID(), name: "owned.gif", size: 6, mediaType: "image/gif" as const, sha256: hash.finish() };
  Object.assign(row, { id: crypto.randomUUID(), userId: crypto.randomUUID(), archivedAuthorName: "Archived author", attachments: [attachment],
    inlineImages: { [attachment.id]: { data: btoa("GIF89a"), mediaType: "image/gif", original: true, width: 1, height: 1 } } });
  const rows = [row, { ...row, id: crypto.randomUUID(), seq: 2, nonce: "second-send", text: "Older and recent rows both remain" }];
  Object.defineProperty(snapshot, "rows", { get: () => (async function* () { yield* rows; })() });
  const retained = vi.spyOn(session.attachments, "retained").mockRejectedValue(new Error("file_inventory_must_not_be_opened"));
  const content = vi.fn(), restored: BackupHistoryRow[] = [];
  try {
    const archive = kind === "backup" ? await session.exportRoomBackup("first", false)
      : await session.exportRoomCopy("first", kind === "copy-with-settings", false);
    const metadata = await backupArchive.readBackup(archive, { metadata: () => {}, row: value => { restored.push(value); }, content });
    expect(metadata).toMatchObject({ kind: kind === "backup" ? "room" : "room_copy", retainedFiles: [] });
    if (kind === "backup") expect(metadata).toMatchObject({ domainId: state.channel.id, policy });
    else if (kind === "copy-with-settings") expect(metadata).toMatchObject({ roomInfo: { name: policy.name, icon: "rocket", picture, voiceBitrate: policy.voiceBitrate, relayCapacity: policy.relayCapacity } });
    else expect(metadata).not.toHaveProperty("roomInfo");
    expect(restored).toEqual(rows); expect(content).not.toHaveBeenCalled(); expect(retained).not.toHaveBeenCalled();
    const zip = await import("@zip.js/zip.js/lib/zip-core-native.js"), reader = new zip.ZipReader(new zip.BlobReader(archive), { useWebWorkers: false });
    try { expect((await reader.getEntries()).map(entry => entry.filename)).toEqual(["manifest.json", "history.ndjson"]); }
    finally { await reader.close(); }
    expect(snapshot.close).toHaveBeenCalledOnce();
  } finally { session.close(); }
});

test("Core archive budget failures stay distinct from malformed retained inventory", async () => {
  const core = await import("../prototype/channel-browser/pkg/piik_channel_browser.js");
  const { readFile } = await import("node:fs/promises");
  await core.default({ module_or_path: await readFile("prototype/channel-browser/pkg/piik_channel_browser_bg.wasm") });
  const limits = JSON.parse(core.attachment_limits());
  const inventory = (sizes: number[]) => sizes.map((size, index) => ({ messageSeq: index + 1,
    attachment: { id: crypto.randomUUID(), name: "owned.bin", size, mediaType: "application/octet-stream", sha256: index.toString(16).padStart(64, "0") } }));
  const validate = (retainedFiles: ReturnType<typeof inventory>) => core.backup_metadata(JSON.stringify({ kind: "room_copy", version: 2, authors: {}, retainedFiles }));
  const count = inventory(Array(limits.maxRetainedFiles).fill(1));
  const sizes = [limits.maxRetainedBytes];
  const bytes = inventory(sizes);
  expect(JSON.parse(validate(count)).retainedFiles).toHaveLength(count.length);
  expect(JSON.parse(validate(bytes)).retainedFiles).toHaveLength(bytes.length);
  expect(() => validate(inventory(Array(limits.maxRetainedFiles + 1).fill(1)))).toThrow("backup_content_limit");
  expect(() => validate(inventory([...sizes, 1]))).toThrow("backup_content_limit");
  expect(() => validate([count[0], count[0]])).toThrow("invalid_backup_content");
  expect(() => validate([count[0], { ...count[1], attachment: { ...count[1].attachment, sha256: count[0].attachment.sha256, size: 2 } }])).toThrow("invalid_backup_content");
});

test("room restore releases staging when its session reconnects during append", async () => {
  const { session, socket, stage, read, metadata, row, state } = await setupRoomBackup();
  stage.close.mockRejectedValueOnce(new Error("stage_cleanup_failed"));
  let resume!: () => void;
  stage.append.mockImplementationOnce(() => new Promise<void>(resolve => { resume = resolve; }));
  read.mockImplementationOnce(async (_blob, visitor) => {
    await visitor?.metadata(metadata);
    await visitor?.row(row);
    await visitor?.row({ ...row, seq: row.seq + 1 });
    return metadata;
  });
  try {
    const restore = session.restoreRoomBackup(new Blob(), "first");
    await expect(session.updateRoom("first", { name: "Locked" })).rejects.toThrow("operation_pending");
    await vi.waitFor(() => expect(stage.append).toHaveBeenCalledOnce());
    socket.close(); session.reconnect();
    const next = ChannelSocket.current; await next.onopen?.();
    next.receive({ type: "welcome", protocol: CHANNEL_PROTOCOL, credential: "credential", sessionId: "endpoint", state });
    resume();
    await expect(restore).rejects.toThrow("disconnected");
    expect(stage.append).toHaveBeenCalledOnce();
    expect(stage.close).toHaveBeenCalledOnce();
    expect(stage.replace).not.toHaveBeenCalled();
  } finally { session.close(); }
});

test.each(["success", "create-failed", "registration-failed", "reconnect-during-cache", "duplicate", "native-success", "native-unconfirmed"] as const)("guest room copy under the channel-assigned ID: %s", async outcome => {
  const { session, socket, state, read, stage, metadata, row, nextHost } = await setupRoomBackup();
  state.channel.ownerId = "another-owner";
  socket.receive({ type: "state", state });
  const id = "domain-created-room";
  const native = outcome === "native-unconfirmed" || outcome === "native-success";
  const encoded = new Blob(["encoded"]);
  if (native) {
    vi.spyOn(appLink, "discoverChannelAppHealth").mockResolvedValue({ service: "piik-channel-app", protocol: appLink.APP_PROTOCOL,
      domainProtocol: CHANNEL_PROTOCOL, port: 8793, token: "approved" });
    const app = await startFixtureApp(session);
    await app.onopen?.();
    app.receive({ id: app.sent.at(-1)!.id, result: null });
    await vi.waitFor(() => expect(session.getSnapshot().appConnected).toBe(true));
    vi.spyOn(appLink.ChannelApp.prototype, "restoreRoom").mockImplementationOnce(async archive => {
      expect(archive).toBe(encoded);
      if (outcome === "native-unconfirmed") throw new Error("room_restore_unconfirmed");
      state.channel.rooms.push({ ...state.channel.rooms[0], id, delivery: { hostSessionId: "native-host", bindingId: "copied-binding" } });
      socket.receive({ type: "state", state });
      return { ...metadata.policy, id, hasPassword: false };
    });
    vi.spyOn(appLink.ChannelApp.prototype, "describeHosting").mockResolvedValue({ sessionId: "native-host", roomIds: [id] });
  }
  const runtime = await hosting.loadRoomHosting();
  vi.mocked(hosting.loadRoomHosting).mockResolvedValue({ ...runtime, createRoomPolicy: async () => stage.policy,
    CopyHistoryImport: class { accept(line: string) { return line; } finish() {} free() {} },
  } as unknown as typeof runtime);
  const copy = { kind: "room_copy", version: 2, authors: {}, retainedFiles: [] } as const;
  read.mockImplementationOnce(async (_blob, visitor) => {
    const source = { ...copy, retainedFiles: [] };
    await visitor!.metadata(source); await visitor!.row(row); return source;
  });
  const write = vi.spyOn(backupArchive, "writeBackup").mockImplementationOnce(async converted => {
    if (converted.kind !== "room") throw new Error("expected converted room");
    metadata.policy = converted.policy;
    stage.policy = JSON.stringify(converted.policy);
    return encoded;
  });
  stage.createRoom.mockImplementation(async policy => { metadata.policy = JSON.parse(policy); stage.policy = policy; });
  nextHost.summary = () => ({ ...metadata.policy, hasPassword: false });
  if (outcome === "create-failed") stage.createRoom.mockRejectedValueOnce(new Error("storage_failed"));
  if (outcome === "duplicate") stage.createRoom.mockRejectedValueOnce(new Error("room_host_conflict"));
  vi.spyOn(session.attachments, "restoreRetained").mockImplementation(async () => {
    if (outcome === "reconnect-during-cache") { session.reconnect(); return false; }
    return true;
  });
  const send = socket.send.bind(socket);
  socket.send = data => {
    send(data);
    const request = JSON.parse(data);
    if (request.room?.id !== id && request.roomId !== id) return;
    queueMicrotask(() => {
      if (request.type === "host_register") {
        if (outcome === "registration-failed") {
          socket.receive({ type: "error", requestId: request.requestId, code: "room_host_conflict" });
          return;
        }
        socket.receive({ type: "host_bound", roomId: id, bindingId: "copied-binding" });
        state.channel.rooms.push({ ...state.channel.rooms[0], id,
          delivery: { hostSessionId: "endpoint", bindingId: "copied-binding" } });
        socket.receive({ type: "state", state });
      }
      socket.receive({ type: "ack", requestId: request.requestId });
    });
  };
  try {
    const importing = session.importRoomCopy(new Blob(), metadata.policy);
    if (outcome === "success" || outcome === "native-success") {
      await expect(importing).resolves.toEqual({ roomId: id, cached: true });
      expect(socket.sent).toContainEqual(expect.objectContaining({ type: "browse", roomId: id }));
    } else {
      const expected = { duplicate: "room_host_conflict", "create-failed": "storage_failed", "registration-failed": "room_restored_connection_failed",
        "reconnect-during-cache": "room_restored_connection_failed", "native-unconfirmed": "room_restore_unconfirmed" };
      await expect(importing).rejects.toThrow(expected[outcome]);
    }
    expect(read).toHaveBeenCalledOnce();
    expect(stage.append.mock.calls).toEqual([[row]]);
    expect(stage.replace).not.toHaveBeenCalled();
    expect(write).toHaveBeenCalledTimes(native ? 1 : 0);
    expect(stage.createRoom).toHaveBeenCalledTimes(native ? 0 : 1);
    if (!native) {
      expect(JSON.parse(stage.createRoom.mock.calls[0][0])).toMatchObject({ id, creatorId: "self" });
      expect(stage.createRoom.mock.calls[0][1]).toBeInstanceOf(AbortSignal);
      expect(runtime.BrowserRoomHost.stage).toHaveBeenCalledWith(hosting.roomDatabaseName("domain", "self"), expect.any(String));
    }
    expect(session.getSnapshot().self?.id).toBe("self");
    expect(socket.sent.some(command => command.type === "delete_room")).toBe(false);
    expect(socket.sent.filter(command => command.type === "cancel_room_creation")).toEqual(
      outcome === "create-failed" || outcome === "duplicate" ? [expect.objectContaining({ roomId: id })] : []);
  } finally { session.close(); }
});

