  const fetch = vi.fn().mockResolvedValueOnce(Response.json({ sessionId: hostSessionId, roomIds: ["first"] }))
    .mockResolvedValueOnce(Response.json({ error: "room_restored_connection_failed" }, { status: 409 }));
